/* GENERATED by gen_hcon_augmented.py -- models are generated.
   SAT_PROPOSAL_UNDERWRITING
   *** UNRATIFIED. This payload is a BUILD-SIDE PROPOSAL from the map's
   augmentation blocks and has NOT been ratified by the modeller. Attributes here
   are not declared on this satellite in data_7.js. Do not treat it as part of the
   ratified vault. ***
   anchor      : HUB_PROPOSAL   (kind: hub, origin: map.anchor)
   track       : unratified
   history     : SCD2
   feeders     : 1 emitted of 2 (one per source view AND run)
   runs        : 1 -- opus_health_v2
   payload     : 2 attribute(s), NULL-PADDED TO THE SATELLITE
   grain       : ONE ROW PER HUB_PROPOSAL_HK
   hashdiff    : SAT_PROPOSAL_UNDERWRITING_HASHDIFF (builder decision BD1), GUARDED against an all-null input (s5.5):
                 without the guard every all-null row hashes to ONE value and the
                 satellite collapses to one row, which looks like change detection.
*/

with feeders as (
    select
        md5(upper('HUB_PROPOSAL|' || (HUB_PROPOSAL_BK__SCRUTINY_NO))) as HUB_PROPOSAL_HK
        , cast(null as varchar) as AGE_PROOF_RECEIVED_INDICATOR
        , SPECIAL_APPROVALS as SPECIAL_APPROVAL_DETAIL
        , 'BJAZ_ENROLL_POL_DTLS' as RECORD_SOURCE
        , 'opus_health_v2' as SOURCE_RUN
        , current_timestamp() as LOAD_DATETIME
    from {{ ref('stage_enroll_pol_dtls') }}
    where (nullif(trim(SCRUTINY_NO),'')) is not null
),

resolved as (
    select
        HUB_PROPOSAL_HK,
        max(case when SOURCE_RUN = 'opus_health_legacy_v4' then AGE_PROOF_RECEIVED_INDICATOR end) as AGE_PROOF_RECEIVED_INDICATOR,
        max(case when SOURCE_RUN = 'opus_health_v2' then SPECIAL_APPROVAL_DETAIL end) as SPECIAL_APPROVAL_DETAIL,
        min(RECORD_SOURCE) as RECORD_SOURCE,
        min(SOURCE_RUN) as SOURCE_RUN,
        min(LOAD_DATETIME) as LOAD_DATETIME
    from feeders
    group by HUB_PROPOSAL_HK
),

hashed as (
    select
        *,
        case when AGE_PROOF_RECEIVED_INDICATOR is not null or SPECIAL_APPROVAL_DETAIL is not null
                     then md5(upper(coalesce(cast(AGE_PROOF_RECEIVED_INDICATOR as varchar), '') || '|' || coalesce(cast(SPECIAL_APPROVAL_DETAIL as varchar), '')))
                end as SAT_PROPOSAL_UNDERWRITING_HASHDIFF
    from resolved
)

select * from hashed
where HUB_PROPOSAL_HK is not null
  and SAT_PROPOSAL_UNDERWRITING_HASHDIFF is not null
